1	import { defineStore } from 'pinia'
2	import { computed, ref } from 'vue'
3	import { mockUsers, type DemoUser } from '../mock/users'
4	
5	const STORAGE_KEY = 'aoqin-demo-user'
6	
7	function readStoredUser() {
8	  if (typeof window === 'undefined') return null
9	  const raw = window.localStorage.getItem(STORAGE_KEY)
10	  if (!raw) return null
11	
12	  try {
13	    const stored = JSON.parse(raw) as Partial<DemoUser>
14	    const canonical = mockUsers.find((user) => user.id === stored.id)
15	    if (!canonical) {
16	      window.localStorage.removeItem(STORAGE_KEY)
17	      return null
18	    }
19	    // Earlier demos persisted the whole user object, allowing renamed sample users to survive upgrades.
20	    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(canonical))
21	    return canonical
22	  } catch {
23	    window.localStorage.removeItem(STORAGE_KEY)
24	    return null
25	  }
26	}
27	
28	export const useAuthStore = defineStore('auth', () => {
29	  const currentUser = ref<DemoUser | null>(readStoredUser())
30	
31	  const roleLabel = computed(() => currentUser.value?.roleName || '未登录')
32	
33	  function login(userId: string) {
34	    const user = mockUsers.find((item) => item.id === userId) || mockUsers[0]
35	    currentUser.value = user
36	    if (typeof window !== 'undefined') {
37	      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(user))
38	    }
39	  }
40	
41	  function logout() {
42	    currentUser.value = null
43	    if (typeof window !== 'undefined') {
44	      window.localStorage.removeItem(STORAGE_KEY)
45	    }
46	  }
47	
48	  return {
49	    currentUser,
50	    roleLabel,
51	    login,
52	    logout,
53	  }
54	})
